<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/payments.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$token=(string)($_GET['token']??$_POST['token']??'');$id=(int)($_GET['invoice']??$_POST['invoice']??0);$s=$db->prepare('SELECT s.client_id FROM client_portal_sessions s WHERE s.token_hash=? AND s.expires_at>NOW()');$s->execute([hash('sha256',$token)]);$session=$s->fetch();if(!$session){http_response_code(403);exit('Invalid or expired portal link.');}$q=$db->prepare('SELECT i.*,COALESCE(c.name,l.name) client_name,COALESCE(c.email,l.email) client_email FROM invoices i LEFT JOIN clients c ON c.id=i.client_id LEFT JOIN leads l ON l.id=i.lead_id WHERE i.id=? AND (i.client_id=? OR i.lead_id=(SELECT lead_id FROM clients WHERE id=?))');$q->execute([$id,$session['client_id'],$session['client_id']]);$i=$q->fetch();if(!$i){http_response_code(404);exit('Invoice not found.');}$secret=paystack_secret_key();if(isset($_GET['reference'])&&$secret){$ref=preg_replace('/[^A-Za-z0-9._-]/','',(string)$_GET['reference']);$ch=curl_init('https://api.paystack.co/transaction/verify/'.rawurlencode($ref));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$secret,'Content-Type: application/json']]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode((string)$raw,true);if($code===200&&($data['status']??false)&&($data['data']['status']??'')==='success'){$amount=((float)($data['data']['amount']??0))/100;$currency=(string)($data['data']['currency']??$i['currency']);$a=$db->prepare('SELECT id FROM invoice_payments WHERE reference=? LIMIT 1');$a->execute([$ref]);if(!$a->fetch()&&$amount>0){$db->beginTransaction();try{$p=$db->prepare('INSERT INTO invoice_payments(invoice_id,lead_id,reference,gateway,amount,currency,status,gateway_transaction_id,paid_at,metadata) VALUES(?,?,?,?,?,?,?,?,?,?)');$p->execute([$id,$i['lead_id']?:null,$ref,'paystack',$amount,$currency,'successful',(string)($data['data']['id']??''),date('Y-m-d H:i:s'),json_encode($data['data'],JSON_THROW_ON_ERROR)]);$paid=(float)$i['amount_paid']+$amount;$balance=max(0,(float)$i['total']-$paid);$status=$balance<=0.00001?'paid':'partially_paid';$db->prepare('UPDATE invoices SET amount_paid=?,balance_due=?,status=? WHERE id=?')->execute([$paid,$balance,$status,$id]);$db->prepare('UPDATE invoice_payment_attempts SET status="successful",gateway_transaction_id=? WHERE reference=?')->execute([(string)($data['data']['id']??''),$ref]);$db->prepare('INSERT INTO invoice_events(invoice_id,event_type,description) VALUES(?,?,?)')->execute([$id,'payment_verified','Paystack payment verified: '.$ref]);$db->commit();}catch(Throwable $ex){$db->rollBack();}}header('Location: invoice.php?token='.urlencode($token).'&invoice='.$id.'&payment=successful');exit;}header('Location: invoice.php?token='.urlencode($token).'&invoice='.$id.'&payment=failed');exit;}$message='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!$secret){$message='Online payment is not configured yet. Please contact us for bank transfer or card-payment instructions.';}else{$ref='DWS-'.date('YmdHis').'-'.bin2hex(random_bytes(4));$attempt=$db->prepare('INSERT INTO invoice_payment_attempts(invoice_id,gateway,reference,amount,currency,status) VALUES(?,?,?,?,?,?)');$attempt->execute([$id,'paystack',$ref,(float)$i['balance_due'],$i['currency'],'initiated']);$payload=json_encode(['email'=>$i['client_email'],'amount'=>(int)round((float)$i['balance_due']*100),'currency'=>$i['currency'],'reference'=>$ref,'callback_url'=>payment_callback_url($token)]);$ch=curl_init('https://api.paystack.co/transaction/initialize');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$payload,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$secret,'Content-Type: application/json']]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode((string)$raw,true);if($code>=200&&$code<300&&($data['status']??false)&&!empty($data['data']['authorization_url'])){header('Location: '.$data['data']['authorization_url']);exit;}$db->prepare('UPDATE invoice_payment_attempts SET status="failed",metadata=? WHERE reference=?')->execute([json_encode($data),$ref]);$message='Unable to initialize online payment. Please try again or contact us.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pay Invoice</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="card mx-auto" style="max-width:650px"><div class="card-body"><h1 class="h4">Pay Invoice <?=$e($i['invoice_number'])?></h1><p>Balance due: <strong><?=$e($i['currency'])?> <?=number_format((float)$i['balance_due'],2)?></strong></p><?php if($message):?><div class="alert alert-warning"><?=$e($message)?></div><?php endif;?><form method="post"><input type="hidden" name="token" value="<?=$e($token)?>"><input type="hidden" name="invoice" value="<?=$id?>"><button class="btn btn-primary" <?=$secret?'':'disabled'?>>Pay securely online</button></form><a class="btn btn-link mt-2" href="invoice.php?token=<?=$e(urlencode($token))?>&invoice=<?=$id?>">Back to invoice</a></div></div></main></body></html>